/**
 * QUICK-POS — Store Registry & Template Engine
 * 
 * Manages multi-store credentials generated by Super Admin,
 * template-based product catalogs (Kiryana, Meat, Biryani, Tailor, Boutique, Custom),
 * and persistent store credential authentication.
 */

import { ProductRecord } from "@/lib/offline/sqlite-db";

export interface StoreAccount {
  id: string;
  store_code: string;
  name: string;
  owner_name: string;
  phone: string;
  login_pin: string;
  area: string;
  template_type: "kiryana" | "meat" | "biryani" | "tailor" | "boutique" | "custom";
  status: "active" | "suspended" | "grace_period" | "trial";
  subscription_status: "paid" | "due" | "overdue";
  next_due_date: string;
  printer_assigned: string | null;
  enabled_modules: string[];
  products: ProductRecord[];
  ntn?: string;
  created_at: string;
}

