const STORAGE_KEYS = {
  STORES: "quickpos_stores_registry_v1",
  CURRENT_STORE_SESSION: "quickpos_active_store_session_v1",
};

export class StoreRegistry {
  private static instance: StoreRegistry;

  private constructor() {
    this.ensureInitialized();
  }

  public static getInstance(): StoreRegistry {
    if (!StoreRegistry.instance) {
      StoreRegistry.instance = new StoreRegistry();
    }
    return StoreRegistry.instance;
  }

  private isBrowser(): boolean {
    return typeof window !== "undefined" && typeof localStorage !== "undefined";
  }

  private ensureInitialized() {
    if (!this.isBrowser()) return;
    const stored = localStorage.getItem(STORAGE_KEYS.STORES);
    if (!stored) {
      localStorage.setItem(STORAGE_KEYS.STORES, JSON.stringify(INITIAL_STORES));
    } else {
      try {
        const existing = JSON.parse(stored) as StoreAccount[];
        const existingCodes = new Set(existing.map((s) => s.store_code.toUpperCase()));
        const missing = INITIAL_STORES.filter((s) => !existingCodes.has(s.store_code.toUpperCase()));
        if (missing.length > 0) {
          const merged = [...existing, ...missing];
          localStorage.setItem(STORAGE_KEYS.STORES, JSON.stringify(merged));
        }
      } catch {
        localStorage.setItem(STORAGE_KEYS.STORES, JSON.stringify(INITIAL_STORES));
      }
    }
  }

  public getStores(): StoreAccount[] {
    if (!this.isBrowser()) return INITIAL_STORES;
    try {
      const data = localStorage.getItem(STORAGE_KEYS.STORES);
      if (!data) return INITIAL_STORES;
      return JSON.parse(data) as StoreAccount[];
    } catch {
      return INITIAL_STORES;
    }
  }

  public getStoreById(id: string): StoreAccount | null {
    const list = this.getStores();
    return list.find((s) => s.id === id || s.store_code.toUpperCase() === id.toUpperCase()) || null;
  }

  public authenticateStore(storeIdentifier: string, pin: string): StoreAccount | null {
    const cleanId = storeIdentifier.trim().toUpperCase();
    const cleanPin = pin.trim();
    const stores = this.getStores();

    const match = stores.find((s) => {
      const codeMatch = s.store_code.toUpperCase() === cleanId;
      const idMatch = s.id.toUpperCase() === cleanId;
      const phoneMatch = s.phone.replace(/[^0-9]/g, "") === cleanId.replace(/[^0-9]/g, "");
      const pinMatch = s.login_pin === cleanPin;

      return (codeMatch || idMatch || phoneMatch) && pinMatch;
    });

    if (match) {
      if (this.isBrowser()) {
        sessionStorage.setItem(STORAGE_KEYS.CURRENT_STORE_SESSION, JSON.stringify(match));
      }
      return match;
    }
    return null;
  }

  public setActiveStoreSession(store: StoreAccount): void {
    if (this.isBrowser()) {
      sessionStorage.setItem(STORAGE_KEYS.CURRENT_STORE_SESSION, JSON.stringify(store));
    }
  }

  public getActiveStoreSession(): StoreAccount | null {
    if (!this.isBrowser()) return null;
    try {
      const data = sessionStorage.getItem(STORAGE_KEYS.CURRENT_STORE_SESSION);
      if (!data) return null;
      return JSON.parse(data) as StoreAccount;
    } catch {
      return null;
    }
  }

  public clearStoreSession(): void {
    if (this.isBrowser()) {
      sessionStorage.removeItem(STORAGE_KEYS.CURRENT_STORE_SESSION);
      sessionStorage.removeItem("quickpos_cashier_session");
    }
  }

  public createStore(data: {
    name: string;
    owner_name: string;
    phone: string;
    area: string;
    template_type: "kiryana" | "meat" | "biryani" | "tailor" | "boutique" | "custom";
    custom_pin?: string;
    custom_store_code?: string;
    custom_products?: ProductRecord[];
    enabled_modules?: string[];
  }): StoreAccount {
    const stores = this.getStores();
    const count = stores.length + 1;
    
    // Use admin-specified store code or auto-generate clean unique code
    const storeCode = data.custom_store_code?.trim()
      ? data.custom_store_code.trim().toUpperCase().replace(/[^A-Z0-9-]/g, "")
      : (
          data.name.replace(/[^A-Za-z0-9]/g, "").slice(0, 6) + "-" + Math.floor(10 + Math.random() * 90)
        ).toUpperCase();

    const pin = data.custom_pin?.trim() || Math.floor(1000 + Math.random() * 9000).toString();

    // Select product catalog template or use custom-built products
    let templateProducts: ProductRecord[] = KIRYANA_PRODUCTS;
    if (data.custom_products && data.custom_products.length > 0) {
      templateProducts = data.custom_products;
    } else if (data.template_type === "meat") {
      templateProducts = MEAT_PRODUCTS;
    } else if (data.template_type === "biryani") {
      templateProducts = BIRYANI_PRODUCTS;
    } else if (data.template_type === "tailor") {
      templateProducts = TAILOR_PRODUCTS;
    } else if (data.template_type === "boutique") {
      templateProducts = BOUTIQUE_PRODUCTS;
    } else if (data.template_type === "custom") {
      templateProducts = CUSTOM_DEFAULT_PRODUCTS;
    }

    const newStore: StoreAccount = {
      id: `shop-${String(count).padStart(2, "0")}`,
      store_code: storeCode,
      name: data.name,
      owner_name: data.owner_name,
      phone: data.phone,
      login_pin: pin,
      area: data.area,
      template_type: data.template_type,
      status: "active",
      subscription_status: "paid",
      next_due_date: "2026-11-30",
      printer_assigned: null,
      enabled_modules: data.enabled_modules || ["Billing", "Inventory", "Customer Khata", "Thermal Print"],
      products: templateProducts,
      created_at: new Date().toISOString().split("T")[0],
    };

    const updated = [newStore, ...stores];
    if (this.isBrowser()) {
      localStorage.setItem(STORAGE_KEYS.STORES, JSON.stringify(updated));
    }
    return newStore;
  }

  public updateStore(store: StoreAccount): void {
    const stores = this.getStores();
    const updated = stores.map((s) => (s.id === store.id ? store : s));
    if (this.isBrowser()) {
      localStorage.setItem(STORAGE_KEYS.STORES, JSON.stringify(updated));
    }
  }

  public addStoreProduct(storeId: string, product: ProductRecord): void {
    const stores = this.getStores();
    const target = stores.find((s) => s.id === storeId || s.store_code === storeId);
    if (!target) return;

    target.products = [product, ...(target.products || [])];
    this.updateStore(target);
  }

  public updateStorePin(storeId: string, newPin: string): void {
    const stores = this.getStores();
    const target = stores.find((s) => s.id === storeId || s.store_code === storeId);
    if (!target) return;

    target.login_pin = newPin.trim();
    this.updateStore(target);
  }

  public deleteStore(storeId: string): void {
    const stores = this.getStores();
    const updated = stores.filter((s) => s.id !== storeId && s.store_code !== storeId);
    if (this.isBrowser()) {
      localStorage.setItem(STORAGE_KEYS.STORES, JSON.stringify(updated));
    }
  }
}

export const storeRegistry = StoreRegistry.getInstance();
